#!/usr/bin/env bash
set -Eeuo pipefail

SCENARIO="/run/armor/scenario.json"
if [[ ! -r "$SCENARIO" ]]; then
  echo '[!] Missing scenario seed. Launch with: python3 armorlab.py up' >&2
  exit 1
fi

# Passwords and ephemeral flags are generated by the host CLI at deployment.
# They are NEVER embedded in the source repository or built image.
eval "$(python3 - "$SCENARIO" <<'PY'
import json, shlex, sys
with open(sys.argv[1], encoding='utf-8') as fh:
    s = json.load(fh)
for name, key in [('ADMIN_PASSWORD','admin_password'),
                  ('SERVICE_PASSWORD','service_password')]:
    print(f'{name}={shlex.quote(s[key])}')
for i in range(1, 5):
    print(f'FLAG_{i}={shlex.quote(s["flags"][f"{i:02d}"])}')
PY
)"

if [[ ! -f /var/lib/samba/private/sam.ldb ]]; then
  echo '[+] Provisioning isolated Samba AD forest ARMOR.TEST'
  mkdir -p /etc/samba /var/lib/samba /srv/armor
  rm -f /etc/samba/smb.conf
  samba-tool domain provision \
    --server-role=dc \
    --realm=ARMOR.TEST \
    --domain=ARMOR \
    --dns-backend=SAMBA_INTERNAL \
    --use-rfc2307 \
    --adminpass="$ADMIN_PASSWORD"

fi

if [[ ! -f /var/lib/samba/.armor-ready ]]; then
  # Deliberately relaxed LDAP simple-bind requirement. Safe ONLY within the private
  # Docker network (internal: true); this is part of a security-misconfiguration lesson.
  if ! grep -Fq '[GA-Public]' /etc/samba/smb.conf; then
  cat >> /etc/samba/smb.conf <<'EOF'

    ldap server require strong auth = no
    map to guest = Never

[GA-Public]
    path = /srv/armor/public
    read only = yes
    browseable = yes
    guest ok = no

[GA-Archive]
    path = /srv/armor/archive
    read only = yes
    browseable = yes
    guest ok = no
    valid users = svc_backup
EOF
  fi

  # A small but genuine AD directory with realistic identities and group memberships.
  samba-tool group list | grep -Fxq GA-Helpdesk || samba-tool group add GA-Helpdesk
  samba-tool group list | grep -Fxq GA-IT-Operations || samba-tool group add GA-IT-Operations
  samba-tool user list | grep -Fxq student01 || samba-tool user create student01 'GreenArmor2026!' --given-name=Student --surname=Analyst \
    --description='Training cohort account. Review GA-Public before making changes.'
  samba-tool user list | grep -Fxq m.salem || samba-tool user create m.salem 'TrainingOnly2026!' --given-name=Mariam --surname=Salem \
    --description='Helpdesk technician'
  samba-tool user list | grep -Fxq t.nasser || samba-tool user create t.nasser 'TrainingOnly2026!' --given-name=Tariq --surname=Nasser \
    --description='IT operations staff'
  samba-tool user list | grep -Fxq svc_backup || samba-tool user create svc_backup "$SERVICE_PASSWORD" --given-name=Archive --surname=Service \
    --description="Legacy archive automation | assessment token: $FLAG_2"
  samba-tool group listmembers GA-Helpdesk | grep -Fxq m.salem || samba-tool group addmembers GA-Helpdesk m.salem
  samba-tool group listmembers GA-IT-Operations | grep -Fxq t.nasser || samba-tool group addmembers GA-IT-Operations t.nasser
  samba-tool group listmembers GA-IT-Operations | grep -Fxq svc_backup || samba-tool group addmembers GA-IT-Operations svc_backup
  samba-tool spn list svc_backup | grep -Fq HTTP/archive.armor.test || \
    samba-tool spn add HTTP/archive.armor.test svc_backup || echo "[!] Optional SPN was not registered."

  # Intentional access-control defects + rotating challenge flags.
  install -d -m 755 /srv/armor/public/IT /srv/armor/public/Projects /srv/armor/archive/reports
  cat > /srv/armor/public/START-HERE.txt <<EOF
GREEN ARMOR ACADEMY // ONBOARDING
Unit: Directory operations assessment
Domain: ARMOR.TEST
Ticket: $FLAG_1

This training folder is accessible to authenticated domain users.
Start with directory discovery and look for service accounts.
EOF
  cat > /srv/armor/public/Projects/architecture.txt <<'EOF'
ARMOR.TEST
  DC01        Samba Active Directory Domain Controller
  GA-Public   General authenticated read-only share
  GA-Archive  Restricted operations archive

Security note: Access to an archive should follow least privilege.
EOF
  cat > /srv/armor/public/IT/legacy-integration.ini <<EOF
# DO NOT USE IN PRODUCTION — deliberately misplaced training configuration
# Example of credentials exposed in a broadly readable file share.
service_username=svc_backup
service_domain=ARMOR
service_password=$SERVICE_PASSWORD
tracking_reference=$FLAG_3
EOF
  cat > /srv/armor/archive/reports/security-review.txt <<EOF
GREEN ARMOR ACADEMY // CONFIDENTIAL ARCHIVE
This folder should never be reachable using exposed service credentials.
Investigation evidence: $FLAG_4

Document the account, weak access path, business impact and mitigation.
EOF
  chmod -R a+rX /srv/armor
  touch /var/lib/samba/.armor-ready
  echo '[+] Directory objects and intentionally weak file shares initialized.'
else
  echo '[+] Existing directory volume found; reusing previous provisioning.'
fi

# Shares live under /srv and need persistence across container re-creations.
# /srv/armor is a named volume (see compose.yaml).
# Generated krb5.conf is useful for administrator diagnostics.
if [[ -f /var/lib/samba/private/krb5.conf ]]; then
  cp /var/lib/samba/private/krb5.conf /etc/krb5.conf
fi
exec samba -i -M single
